import {DEFAULT_REMINDERS,reminderQueue,dueReminders,offsetLabel,normalizeOffsets,calendarExport,reminderSummary} from './reminders-core.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function reminderFields({values=DEFAULT_REMINDERS,inherit=false,defaults=DEFAULT_REMINDERS,global=false}={}){
 const current=values??defaults,options=[...new Set([1440,60,30,10,0,...current])].sort((a,b)=>b-a);
 return `<div class="reminder-fields" data-defaults="${escape(JSON.stringify(defaults))}">${!global?`<label class="check-label"><input type="checkbox" name="inheritReminders" ${inherit?'checked':''}> Varsayılan: ${escape(reminderSummary(defaults))}</label>`:''}<fieldset class="reminder-choices" ${inherit?'disabled':''}><legend class="sr-only">Hatırlatma süreleri</legend><div class="reminder-chips">${options.map(n=>`<label class="reminder-chip"><input type="checkbox" name="reminderOffset" value="${n}" ${current.includes(n)?'checked':''}><span>${escape(offsetLabel(n))}</span></label>`).join('')}</div><div class="reminder-custom"><input type="number" name="customReminderAmount" aria-label="Özel hatırlatma süresi" min="1" max="525600" placeholder="Süre"><select name="customReminderUnit" aria-label="Hatırlatma birimi"><option value="1">dakika</option><option value="60">saat</option><option value="1440">gün</option></select><button type="button" data-add-reminder class="button secondary small">Ekle</button></div></fieldset><p class="reminder-form-error" role="alert"></p></div>`;
}
export function readReminderFields(fd){if(fd.has('inheritReminders'))return null;return normalizeOffsets(fd.getAll('reminderOffset').map(Number))}
document.addEventListener('change',e=>{if(e.target.name==='inheritReminders'){const fields=e.target.closest('.reminder-fields');fields.querySelector('fieldset').disabled=e.target.checked;fields.dispatchEvent(new Event('input',{bubbles:true}));}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-add-reminder]');if(!b)return;e.preventDefault();const w=b.closest('.reminder-fields'),n=w.querySelector('[name=customReminderAmount]'),unit=w.querySelector('[name=customReminderUnit]'),error=w.querySelector('.reminder-form-error'),minutes=Number(n.value)*Number(unit.value);error.textContent='';if(!n.value||!Number.isInteger(minutes)||minutes<1||minutes>525600){error.textContent='1 dakika ile 365 gün arasında bir süre gir.';return;}const chips=w.querySelector('.reminder-chips'),existing=chips.querySelector(`input[value="${minutes}"]`);if(existing)existing.checked=true;else{if(chips.querySelectorAll('input:checked').length>=5){error.textContent='En fazla beş hatırlatma seçebilirsin.';return;}chips.insertAdjacentHTML('beforeend',`<label class="reminder-chip"><input type="checkbox" name="reminderOffset" value="${minutes}" checked><span>${offsetLabel(minutes)}</span></label>`);}n.value='';w.dispatchEvent(new Event('input',{bubbles:true}));});
export function setupReminders({getState,commit,notify=()=>{}}){
 let timer,queue=[],lastBuild=0,revision=-1,registration=null,working=false,dbPromise,lastCheck=0;
 const support=()=>('Notification'in window)&&('serviceWorker'in navigator);
 const permission=()=>support()?Notification.permission:'unsupported';
 const storage=()=>dbPromise??=(new Promise((resolve,reject)=>{const r=indexedDB.open('gun-payi-reminders',1);r.onupgradeneeded=()=>r.result.createObjectStore('delivered',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}));
 const claim=async reminder=>{const db=await storage();return new Promise((resolve,reject)=>{const tx=db.transaction('delivered','readwrite');tx.objectStore('delivered').add({id:reminder.id,at:Date.now()});tx.oncomplete=()=>resolve(true);tx.onabort=()=>resolve(false);tx.onerror=()=>{}})};
 const unclaim=async id=>{const db=await storage();return new Promise(resolve=>{const tx=db.transaction('delivered','readwrite');tx.objectStore('delivered').delete(id);tx.oncomplete=tx.onabort=resolve})};
 function diagnostic(){return lastCheck?'Son yerel kontrol: '+new Date(lastCheck).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})+' · yalnız sayfa çalışırken':'Henüz yerel zaman kontrolü yapılmadı. Deneme bildirimi zamanlayıcı testi değildir.';}
 async function tick(){if(working||!getState()||!registration||permission()!=='granted'||getState().prefs.notifyEnabled===false)return;working=true;lastCheck=Date.now();const label=document.getElementById('local-reminder-status');if(label)label.textContent=diagnostic();try{const state=getState(),now=Date.now();if(state.revision!==revision||now-lastBuild>60000){queue=reminderQueue(state,now,370,30*60000);revision=state.revision;lastBuild=now;}for(const n of dueReminders(queue,now,30*60000)){if(!await claim(n))continue;try{await registration.showNotification(n.title,{body:n.minutes?`${n.due<now-120000?'Gecikmiş hatırlatma · ':''}${offsetLabel(n.minutes)} · ${new Date(n.start).toLocaleString('tr-TR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}`:'Etkinliğin şimdi başlıyor.',icon:'/icons/icon-192.png',badge:'/icons/icon-192.png',tag:n.id,data:{date:n.date,url:`/?date=${n.date}`}})}catch{await unclaim(n.id);}}}catch{}finally{working=false;}}
 async function enable(){if(!support()){notify('Bu tarayıcı sistem bildirimlerini desteklemiyor. Takvime aktarmayı kullanabilirsin.');return;}let p=permission();try{if(p==='default')p=await Notification.requestPermission();if(p!=='granted'){notify('Bildirim izni verilmedi. Tarayıcı veya telefon ayarlarından açabilirsin.');return;}if(await commit(s=>s.prefs.notifyEnabled=true)){notify('Uygulama açıkken hatırlatmalar etkin.');revision=-1;tick();}}catch{notify('Bildirim izni açılamadı. iPhone’da ana ekrandan açmayı deneyebilirsin.');}}
 async function test(){if(permission()!=='granted'){await enable();return;}if(!registration){notify('Uygulamayı bir kez yeniden açıp tekrar dene.');return;}try{await registration.showNotification('Gün Payı',{body:'Sistem bildirimi bu cihazda çalışıyor. Bu deneme, kapalı uygulamada zamanlanmış bildirim desteği değildir.',icon:'/icons/icon-192.png',tag:'gun-payi-test',data:{url:'/'}});notify('Deneme bildirimi gönderildi.')}catch{notify('Sistem bildirimi gösterilemedi. Cihaz bildirim ayarlarını kontrol et.');}}
 function exportCalendar(){const result=calendarExport(getState());if(!result.count){notify('Aktarılacak saatli bir etkinlik yok. Önce tarih ve saat ekle.');return;}const url=URL.createObjectURL(new Blob([result.text],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='gun-payi-takvim.ics';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);notify(`${result.count} saatli plan takvim dosyasına aktarıldı. Telefon takviminde içe aktar.`);}
 function attach(reg){registration=reg;clearInterval(timer);timer=setInterval(tick,5000);tick();}
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});window.addEventListener('pagehide',()=>clearInterval(timer));window.addEventListener('pageshow',()=>{if(registration)attach(registration)});
 return {attach,refresh:()=>{revision=-1;tick()},enable,test,exportCalendar,permission,diagnostic,supported:support};
}
